    int[] counts = countShowAsActions(element);
    int alwaysCount = counts[0];
    int ifRoomCount = counts[1];
    if (alwaysCount > 2) {
        context.report(ISSUE, context.getLocation(element),
            "Menu has " + alwaysCount + " showAsAction=\"always\" items; using more than two is not recommended");
    } else if (alwaysCount > 0 && ifRoomCount == 0) {
        context.report(ISSUE, context.getLocation(element),
            "Menu has showAsAction=\"always\" items but no showAsAction=\"ifRoom\" items");
    }
}

private int[] countShowAsActions(Element menu) {
    int always = 0, ifRoom = 0;
    NodeList items = menu.getElementsByTagName(ITEM); // returns all descendant item elements
    for (int i=0; i<items.getLength(); i++) {
        Element item = (Element) items.item(i);
        String value = getShowAsActionValue(item);
        if (value != null) {
            for (String flag : value.split("\\|")) {
                String trimmed = flag.trim();
                if (ALWAYS.equals(trimmed)) always++;
                else if (IF_ROOM.equals(trimmed)) ifRoom++;
            }
        }
    }
    return new int[]{always, ifRoom};
}

private String getShowAsActionValue(Element item) {
    if (item.hasAttribute(SHOW_AS_ACTION)) return item.getAttribute(SHOW_AS_ACTION);
    if (item.hasAttribute("android:" + SHOW_AS_ACTION)) return item.getAttribute("android:" + SHOW_AS_ACTION);
    if (item.hasAttribute("app:" + SHOW_AS_ACTION)) return item.getAttribute("app:" + SHOW_AS_ACTION);
